{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, had an absolute oral bioavailability of only 0.5–1% in healthy subjects after daily oral dosing, directly supporting very low absorption for sulfated carbohydrate structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Acarbose, a carbohydrate-based drug, showed negligible absolute oral bioavailability (<2%) in humans based on plasma and urinary recovery versus IV, supporting low F for polar saccharide drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Glycyrrhizin, a glycoside bearing glucuronic acid units, had an oral bioavailability of approximately 0.25% versus injections in humans, supporting low F for glucuronic-acid-containing glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dextran sulfate, another highly sulfated carbohydrate, was reported to have poor oral bioavailability in humans, consistent with poor absorption of sulfated saccharides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Scutellarin, a polar glucuronide conjugate, had an estimated oral bioavailability of only 10.67% in humans, below the 20% threshold, supporting low F for polar glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Furosemide acyl glucuronide, a polar glucuronide metabolite, had an oral bioavailability of about 15% in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, ionized sulfated disaccharide containing glucuronic acid and sulfate groups. Direct analogues of sulfated and carbohydrate-containing drugs—pentosan polysulfate, dextran sulfate, acarbose, glycyrrhizin, and glucuronide conjugates—all show oral bioavailability well below 20%, strongly supporting a low F prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule.",
    "Potential active transport or carrier-mediated absorption for this specific disaccharide is not experimentally assessed.",
    "Exact sulfate position and charge may alter transporter interactions, but passive permeability is expected to be negligible based on the analogue evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

